(* [comment removed for export] *)
Lemma ric_unslotV cr pot0 t0 cr1 pp pa1 t1 cr2 pa2 t2 v1 v2 :
  ric cr pot0 t0 cr1 (PM.credit_add pp pa1) t1 ->
  PMSP.credit_keep cr1 cr2 (PM.credit_add pa1 v1) (PM.credit_add pa2 v2) ->
  PMSP.credit_le (PM.credit_add t2 v1) (PM.credit_add t1 v2) ->
