(* [comment removed for export] *)
Lemma mparser_set_tbS op ois s (x0 : PM.vstr) :
  0 <= op -> op + PQMA.PSIZE <= 2 ^ 64 ->
  mem_grows M M' -> PMFA.agA M M' op 328 -> PMFA.agA M M' (op + 352) 48 -> PMFA.agsh M M' op PQMA.PSIZE ->
  PM.vstr_at segs accA M' (op + 328) x0 ->
  (forall B m, In (B, m) (PQAKWT.tb_rest_own s) -> 0 <= B /\ B + m <= 2 ^ 64 /\ PMFA.agA M M' B m) ->
