Lemma binv_calleeX Dc D2 W1 BX BXa BX1 Mc modelc LKc crc Ac M1 model1 LK1 cr1 A1 (spx SCRc : Z) (Wc : list L5.range) :
  PQAKUF.binv L ar HIk Dc M model LBX FF LK Aw sp SCR spc own F 4 WR BX Mc modelc LKc crc Ac ->
  L5CA.ahpres L ar (BXa ++ LBX) FF' spx SCRc Wc Mc M1 ->
  ri_inv (HIk D2) (BX1 ++ LBX) FF' LK1 cr1 A1 M1 (vml_of model1) -> L5CA.amodel_ok A1 model1 -> model_rt modelc model1 -> incl Ac A1 -> incl LK1 LKc ->
  0 <= SCRc -> sp - SCR <= spx - SCRc -> spc - 32 <= spx <= spc ->
  (forall rr a, In rr Wc -> L5.in_rng rr a -> ~ ocell a /\ ~ (F / 8 + SB <= a < F / 8 + SB + B / 8)) ->
  (forall a, aclient L ar LBX FF sp SCR a -> L5.outside W1 a -> L5.outside Wc a) ->
  (forall a, L5.outside W1 a -> L5.outside WR a) ->
  PQAKUF.binv L ar HIk D2 M model LBX FF LK Aw sp SCR spc own F 4 W1 BX1 M1 model1 LK1 cr1 A1.
