  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spx ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 992) ->
  args R1 M1 FF' (PQMA.mparser_own s1 ++ LBX) (fb + 992) (fb + 496) (fb + 432) (fb + 1232) -> pre R1 M1 sa1 ->
  PMSP.credit_le (NEMA.pot_aeA L ar sa1) cr1 ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 sa3 e3 b3 cr3,
      regs_preserved R1 R2 ->
      ri_mem RC Dc M3 model3 LK3 Aw3 s1 sa3 sm1 e3 cr3 b3 ->
      NEMA.ae_ok sa3 -> (b1 = true -> b3 = true) -> (e1 = true -> e3 = true) -> step R1 M1 sa1 sa3 b1 b3 ->
      PMSP.credit_keep cr1 cr3 (NEMA.pot_aeA L ar sa1) (NEMA.pot_aeA L ar sa3) ->
      (forall a, spx <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
Proof using All.
