(* [comment removed for export] *)
Lemma ri_call_mrun RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (pc ra h d : Z)
      (args : bvmap 5 word -> Z -> PQMA.mpst -> NEMA.aest -> PM.strm -> Z -> Prop) (prog : PNRNA.mprog) :
  PNRNA.mrun_spec_d RSEGS AD AQ AAD AE L ar (HIk Dc) pc h d args prog -> 1 <= h <= 9 ->
  ri_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  PQMA.cpl s1 (NEMA.ae_a sa1) -> PQMA.acct n s1 (NEMA.ae_a sa1) sm1 -> NEMA.oacct n s1 sa1 sm1 -> NEMA.ebound sa1 -> (b1 = false -> NEMA.bal sa1) -> PQRA.minv_d d s1 ->
  args R1 fb s1 sa1 sm1 n ->
  PMSP.credit_le (PM.credit_add (pot_runA s1 sa1) (PMSPA.scA L PNRNA.TSRES_ME)) cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3,
      regs_preserved R1 R2 ->
      ri_mem RC Dc M3 model3 LK3 Aw3 s3 sa3 sm3 e3 cr3 b3 ->
      ((b3 = true)
       \/ (b3 = false /\ PQMA.cpl s3 (NEMA.ae_a sa3) /\ PQMA.acct n s3 (NEMA.ae_a sa3) sm3 /\ NEMA.oacct n s3 sa3 sm3 /\ NEMA.ebound sa3 /\ NEMA.bal sa3
           /\ PQRA.minv_d d s3 /\ prog R2 M3 s1 s3 sa1 sa3 sm1 sm3 /\ PQRA.room_keep s1 s3 sm1 sm3)) ->
      PMSP.credit_keep cr1 cr3 (pot_runA s1 sa1) (pot_runA s3 sa3) ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F + 32 <= a < F + B - 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
