(* [comment removed for export] *)
Lemma ri_call_rspan RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (ra len : Z) :
  PQRAa.read_span_v_spec L ar (HIk Dc) ->
  ri_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 (fb + 592 + 24) -> getr R1 (reg 11) = Z_to_bv 64 len -> getr R1 (reg 12) = Z_to_bv 64 (fb + 592 + 352) ->
  0 <= len < 2 ^ 64 -> PM.unread (PQMA.p_src s1) sm1 < 2 ^ 26 -> PGV8.v8_room (PQMA.p_bb s1) (PM.unread (PQMA.p_src s1) sm1) ->
  PMSP.credit_le (PM.credit_add (pot_runA s1 sa1) (PMSPA.scA L PNRNA.TSRES_ME)) cr1 ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 src3 bb3 bg3 sm3 cr3 ptr cnt,
      regs_preserved R1 R2 -> getr R2 (reg 10) = Z_to_bv 64 ptr -> getr R2 (reg 11) = Z_to_bv 64 cnt -> 0 <= cnt <= len -> cnt < 2 ^ 26 ->
      PMSP.consumed (PQMA.p_src s1) src3 sm1 sm3 = cnt ->
      ((ptr = 0 /\ cnt = 0) \/ PGS.in_blk (PQMA.mparser_own (PQMA.with_src_bb s1 src3 bb3 bg3)) ptr cnt) ->
      L5.defined M3 ptr cnt -> PMSPA.accA M3 ptr cnt ->
      (cnt = len -> PGV8.v8_room bb3 (PM.unread src3 sm3)) ->
      PM.unread src3 sm3 <= PM.unread (PQMA.p_src s1) sm1 ->
      ri_mem RC Dc M3 model3 LK3 Aw3 (PQMA.with_src_bb s1 src3 bb3 bg3) sa1 sm3 e1 cr3 b1 ->
      PMSP.credit_keep cr1 cr3 (PMSPA.scA L (PQMA.pot_mparser (PMSPA.HV L ar) s1)) (PMSPA.scA L (PQMA.pot_mparser (PMSPA.HV L ar) (PQMA.with_src_bb s1 src3 bb3 bg3))) ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F <= a < F + B - 8 -> ~ (F + 24 <= a < F + 32) -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0xd3324 M1 model1) K.
Proof using All.
