(* [comment removed for export] *)
Lemma span_facts RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (ptr cnt : Z) :
  ri_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  0 <= cnt < 2 ^ 26 ->
  ((ptr = 0 /\ cnt = 0) \/ PGS.in_blk (PQMA.mparser_own s1) ptr cnt) ->
  0 <= ptr /\ (cnt = 0 \/ 0 < ptr) /\ ptr + cnt <= 2 ^ 47
  /\ (forall a, ptr <= a < ptr + cnt -> ahid Aw1 model1 (Z_to_bv 64 a) = false /\ ahid Aw1 model1 (Z_to_bv 64 (S a)) = false)
  /\ (cnt = 0 \/ spc <= ptr \/ ptr + cnt <= spc - 12288)
  /\ (ptr + cnt <= fb + 992 \/ fb + 992 + PQMA.ASIZE <= ptr)
  /\ (cnt = 0 \/ ptr + cnt <= F \/ F + B <= ptr)
  /\ (cnt = 0 \/ ptr + cnt <= BIGSHADOW_LO \/ BIGSHADOW_HI <= ptr)
  /\ (ptr + cnt <= fb + 32 \/ fb + 2040 <= ptr)
  /\ (cnt = 0 \/ PGS.in_blk (PQMA.mparser_own s1 ++ LBX) ptr cnt).
