Lemma oblk_facts RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (q m : Z) :
  ri_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  In (q, m) (PQMA.mparser_own s1) ->
  4096 <= q /\ 0 < m /\ q + m <= 2 ^ 47 /\ q mod 16 = 0
  /\ (q + m <= BIGSHADOW_LO \/ BIGSHADOW_HI <= q)
  /\ (q + m <= 65536 \/ 7036928 <= q)
  /\ (forall a, q <= a < q + m -> ahid Aw1 model1 (Z_to_bv 64 a) = false /\ ahid Aw1 model1 (Z_to_bv 64 (S a)) = false)
  /\ q + m <= spc - 12288
  /\ (q + m <= fb + 32 \/ fb + 2040 <= q)
  /\ (q + m <= F \/ F + B <= q).
Proof using All.
