(* [comment removed for export] *)
Lemma bytes_of_defined Mx a : forall (m : nat), L5.defined Mx a (Z.of_nat m) -> 0 <= a -> a + Z.of_nat m <= 2 ^ 64 ->
  exists bs, length bs = m /\ L5.bytes_at RSEGS Mx a bs /\ NEM.bytes_ok bs.
Proof.
