Lemma ri_call_valid RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 (fx1 : FPState) R1 (ra p cnt : Z) :
  PECVSA.validate_fun_spec RSEGS AD L ar (HIk Dc) (pa_validate AD) ->
  ri_mem RC Dc M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 p -> getr R1 (reg 11) = Z_to_bv 64 cnt ->
  0 <= cnt < 2 ^ 26 ->
  ((p = 0 /\ cnt = 0) \/ PGS.in_blk (PQMA.mparser_own s1) p cnt) ->
  L5.defined M1 p cnt -> PMSPA.accA M1 p cnt ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 (l : list Z) (v : Z),
      regs_preserved R1 R2 ->
      ri_mem RC Dc M3 model3 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
      L5.bytes_at RSEGS M1 p l -> Z.of_nat (length l) = cnt -> NEM.bytes_ok l ->
      getr R2 (reg 11) = Z_to_bv 64 v -> 0 <= v < 7 -> (v = 0 <-> utf8_valid l = true) ->
      (forall a, spc <= a < 2 ^ 47 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F <= a < F + B - 8 -> ~ (F + 24 <= a < F + 32) -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      mem_grows M1 M3 ->
      (forall a, 0 <= a < 2 ^ 64 -> ~ (spc - 12288 <= a < spc) -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 (pa_validate AD) M1 model1) K.
