(* [comment removed for export] *)
Lemma ri_fin RC Dc M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 b5 (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) :
  ri_mem RC Dc M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 b5 ->
  msteps RSEGS (st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (st fx9 R9 r M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ PQAKUF.WretX F fl 4 (fun _ => False) a -> M9v (Z_to_bv 64 a) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 a)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  regs_preserved R R9 ->
  ( (b5 = true)
    \/ (b5 = false /\ PQMA.cpl s5 (NEMA.ae_a sa5) /\ PQMA.acct n s5 (NEMA.ae_a sa5) sm5 /\ NEMA.oacct n s5 sa5 sm5 /\ NEMA.ebound sa5 /\ NEMA.bal sa5
        /\ PQRA.minv_d 0 s5 /\ (forall Mf, PNRNA.mprog_item R9 Mf s s5 sa sa5 sm sm5) /\ PQRA.room_keep s s5 sm sm5) ) ->
  PMSP.credit_keep cr cr5 (PM.credit_add (pot_runA s sa) (tsp D0 RC0)) (PM.credit_add (pot_runA s5 sa5) (tsp Dc RC0)) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
Proof using All.
